function StatePanel({ title, detail, action }: { title: string; detail: string; action?: ReactNode }) { return <div className="card" style={{padding:32,textAlign:'center',minHeight:220,display:'grid',placeContent:'center',justifyItems:'center',gap:12}}><div style={{width:44,height:44,borderRadius:14,display:'grid',placeItems:'center',background:'var(--green-pale)',color:'var(--green)'}}><Sprout size={22}/></div><h3 className="font-display" style={{margin:0,fontSize:19}}>{title}</h3><p style={{margin:0,color:'var(--muted)',fontSize:13,maxWidth:390,lineHeight:1.6}}>{detail}</p>{action}</div>; }
function SectionHeading({ title, href, link = 'View all' }: { title: string; href?: string; link?: string }) { return <div style={{display:'flex',alignItems:'center',justifyContent:'space-between',marginBottom:14}}><h2 className="font-display" style={{fontSize:16,letterSpacing:'-.03em',margin:0}}>{title}</h2>{href&&<Link href={href} style={{fontSize:12,color:'var(--green)',fontWeight:700,display:'flex',alignItems:'center',gap:5}}>{link}<ArrowRight size={14}/></Link>}</div>; }
