  if(path==='/company/campaigns') return panel(<><div style={{display:'flex',justifyContent:'space-between',alignItems:'center'}}><SectionHeading title="Field programmes"/><button className="btn-primary" onClick={()=>toast('Campaign setup opened.') }><Plus size={15}/> New campaign</button></div>{[['Monsoon seed support','1,284 farmers reached','Ends 30 Jun',72],['Soil-first practices','762 farmers reached','Ends 18 Jul',48],['Harvest assurance','496 farmers reached','Ends 10 Aug',31]].map(x=><div key={x[0]} style={{padding:'16px 0',borderBottom:'1px solid var(--line)'}}><div style={{display:'flex',justifyContent:'space-between',fontSize:12,fontWeight:700}}><span>{x[0]}</span><span className="pill">{x[2]}</span></div><div style={{fontSize:10,color:'var(--muted)',marginTop:5}}>{x[1]}</div><div style={{height:6,background:'var(--surface-soft)',borderRadius:6,marginTop:12}}><div style={{height:'100%',width:`${x[3]}%`,background:'var(--green)',borderRadius:6}}/></div></div>)}</>);
