  if(path==='/expert/questions') return panel(<><div style={{display:'flex',justifyContent:'space-between',alignItems:'center',marginBottom:10}}><div><div className="eyebrow">COMMUNITY INBOX</div><div style={{fontSize:12,color:'var(--muted)',marginTop:4}}>Prioritised by urgency and time waiting.</div></div><button className="btn-secondary" onClick={()=>toast('Showing all open questions.')}><Activity size={14}/> Open · 8</button></div>{[['Urgent','Leaf curl on tomato seedlings','Arjun Patel · Nashik · 12 min ago'],['Today','Yellowing leaves after rainfall','Kavita More · Pune · 46 min ago'],['Today','Soil pH before chickpea sowing','Dinesh Pawar · Satara · 2 hr ago'],['New','Preventing thrips in onion crop','Rekha Shinde · Nashik · 3 hr ago']].map(x=><div key={x[1]} style={{display:'flex',alignItems:'center',gap:12,padding:'14px 0',borderBottom:'1px solid var(--line)'}}><span className="pill" style={{background:x[0]==='Urgent'?'#f8eee4':'var(--green-pale)',color:x[0]==='Urgent'?'var(--amber)':'var(--green-deep)'}}>{x[0]}</span><div style={{flex:1}}><div style={{fontSize:12,fontWeight:700}}>{x[1]}</div><div style={{fontSize:10,color:'var(--muted)',marginTop:4}}>{x[2]}</div></div><button className="btn-primary" style={{padding:'8px 11px',fontSize:10}} onClick={()=>toast(`Answer editor opened for ${x[1]}.`)}>Write answer</button></div>)}</>);
