  if(path==='/expert/knowledge') return <div className="grid-layout" style={{gridTemplateColumns:'repeat(2,minmax(0,1fr))'}}>{[['FIELD GUIDE','Reading early signs of tomato leaf curl','Spot the first symptoms and protect young plants.','6 min'],['SOIL HEALTH','Build better soil between growing seasons','Cover crops, compost and a practical rotation plan.','8 min'],['POST-HARVEST','A practical guide to onion storage','Reduce spoilage with careful curing and ventilation.','5 min'],['CROP CARE','Managing grapes through fruit development','A seasonal checklist for healthy, even bunches.','7 min']].map(x=>panel(<><div className="eyebrow">{x[0]}</div><div style={{width:'100%',height:82,marginTop:10,borderRadius:12,background:'linear-gradient(125deg,var(--green-pale),var(--surface-soft))',display:'grid',placeItems:'center',color:'var(--green)'}}><BookOpen size={26}/></div><h3 className="font-display" style={{fontSize:15,margin:'13px 0 6px'}}>{x[1]}</h3><p style={{fontSize:11,color:'var(--muted)',lineHeight:1.6,minHeight:35}}>{x[2]}</p><div style={{display:'flex',justifyContent:'space-between',alignItems:'center'}}><span style={{fontSize:10,color:'var(--muted)'}}>{x[3]} read</span><button className="btn-secondary" onClick={()=>toast(`Opening “${x[1]}”.`)}>Read guide <ArrowRight size={13}/></button></div></>,{boxShadow:'none'}))}</div>;
